'<b>🗣️ For her voice</b>',
'Take a <b>.gguf</b> file. On the model page (« Files » tab), pick the one ending in <b>Q4_K_M.gguf</b>: the best balance. Your PC has {} GB of memory: take a file <b>under {} GB</b>. Names with « Instruct » or « Chat » can chat; « Translate » ones are made for translating.',
'Take a <b>.safetensors</b> file of type « Checkpoint » (full model). On Civitai, filter by « Checkpoint ». SD 1.5 runs anywhere; SDXL and FLUX need a good graphics card.',
'Take an <b>ACE-Step</b> model as <b>.safetensors</b> (« all in one » / « aio » version).',
'Take <b>both</b> files of a Piper voice: the <b>.onnx</b> and the <b>.onnx.json</b> (drag the .onnx, keep the .json next to it), or a .zip containing them.',
"⛔ I refuse <b>.ckpt</b>, <b>.pt</b> and <b>.bin</b> files: this old format can hide a program. There is almost always a .safetensors or .gguf version. Viki's filters (no shocking images) stay on whatever the model.",
